{
  "packageManager": "yarn@4.18.0",
  "name": "pumila",
  "version": "0.1.1",
  "description": "Cumulo Workflow",
  "main": "index.js",
  "scripts": {
    "compile-page": "calcit calcit.cirru js",
    "release-page": "vite build --base=${VITE_BASE_URL:-./}",
    "watch-page": "calcit calcit.cirru js --watch"
  },
  "repository": {
    "type": "git",
    "url": "git@github.com:mvc-works/cumulo-workflow.git"
  },
  "author": "jiyinyiyong",
  "license": "MIT",
  "dependencies": {
    "@calcit/procs": "0.27.0",
    "dayjs": "^1.11.18",
    "shortid": "^2.2.17"
  },
  "devDependencies": {
    "bottom-tip": "^0.1.5",
    "feather-icons": "^4.29.2",
    "url-parse": "^1.5.10",
    "vite": "^8.2.2"
  }
}

